bool extract_tar_to_path(const std::string& tar_path, const std::string& dest_path) {
    struct archive *src = archive_read_new();
    struct archive *out;
    struct archive_entry *entry;
    int flags = ARCHIVE_EXTRACT_TIME | ARCHIVE_EXTRACT_PERM | ARCHIVE_EXTRACT_NO_OVERWRITE;
    int r;
    char full_path[4096];

    if (!src) {
        return false;
    }

    archive_read_support_format_all(src);
    archive_read_support_filter_all(src);

    r = archive_read_open_filename(src, tar_path.c_str(), 10240);
    if (r != ARCHIVE_OK) {
        archive_read_free(src);
        return false;
    }

    out = archive_write_disk_new();
    if (!out) {
        archive_read_free(src);
        return false;
    }
    archive_write_disk_set_options(out, flags);

    // Ensure the destination directory exists
    if (mkdir(dest_path.c_str(), 0777) != 0 && errno != EEXIST) {
        archive_write_free(out);
        archive_read_free(src);
        return false;
    }

    while ((r = archive_read_next_header(src, &entry)) == ARCHIVE_OK) {
        const char *entry_path = archive_entry_pathname(entry);
        if (!entry_path || *entry_path == '\0') {
            archive_write_free(out);
            archive_read_free(src);
            return false;
        }

        // Validate and sanitize the path to prevent directory traversal
        if (strncasecmp(entry_path, "..", 2) == 0 || strstr(entry_path, "/../") != nullptr) {
            archive_write_free(out);
            archive_read_free(src);
            return false;
        }

        // Construct full path
        snprintf(full_path, sizeof(full_path), "%s/%s", dest_path.c_str(), entry_path);
        archive_entry_set_pathname(entry, full_path);

        r = archive_write_header(out, entry);
        if (r != ARCHIVE_OK) {
            archive_write_free(out);
            archive_read_free(src);
            return false;
        }

        const void *buff;
        size_t size;
        la_int64_t offset;
        while ((r = archive_read_data_block(src, &buff, &size, &offset)) == ARCHIVE_OK) {
            if (archive_write_data_block(out, buff, size, offset) != ARCHIVE_OK) {
                archive_write_free(out);
                archive_read_free(src);
                return false;
            }
        }
        if (r != ARCHIVE_EOF) {
            archive_write_free(out);
            archive_read_free(src);
            return false;
        }
    }

    archive_read_close(src);
    archive_read_free(src);
    archive_write_free(out);
    return r == ARCHIVE_EOF ? true : false;
}
